import numpy as np
la=np.array(L)!=0; ra=np.array(R)!=0; oa=np.array(O)!=0
for xname,x in [('L',la),('R',ra)]:
 for k in range(4):
  for ref in (False,True):
   t=np.rot90(x,k)
   if ref:t=np.fliplr(t)
   if t.shape==oa.shape:
    print(xname,k,ref,'match',np.sum(t==oa),'inter',np.sum(t&oa))

for k in range(4):
 for ref in (False,True):
  t=np.rot90(ra,k)
  if ref:t=np.fliplr(t)
  if t.shape==oa.shape:
   for name,z in [('and',la&t),('l-r',la&~t),('r-l',t&~la),('xor',la^t),('or',la|t)]:
    print(k,ref,name,np.sum(z==oa),np.sum(z),np.sum(oa))

best=[]
for k in range(4):
 for ref in (False,True):
  t=np.rot90(ra,k)
  if ref:t=np.fliplr(t)
  if t.shape!=la.shape: continue
  for dr in range(-8,9):
   for dc in range(-12,13):
    sh=np.zeros_like(t)
    # set sh[i,j]=t[i-dr,j-dc]
    for i in range(9):
     for j in range(13):
      if 0<=i-dr<9 and 0<=j-dc<13: sh[i,j]=t[i-dr,j-dc]
    z=la&sh
    score=np.sum(z==oa)
    best.append((score,k,ref,dr,dc,int(z.sum())))
sorted(best,reverse=True)[:10]
